const err = $input.first().json;
const summary = {
  workflow: err.workflow?.name || err.workflow?.id || 'unknown',
  executionId: err.execution?.id,
  lastNode: err.execution?.lastNodeExecuted,
  message: err.execution?.error?.message || err.message || 'unknown error',
  at: new Date().toISOString(),
};
console.error('[LendLoop n8n ERROR]', JSON.stringify(summary, null, 2));
// Visible in n8n Executions UI; optionally forward to Slack/PagerDuty here.
return [{ json: summary }];
